import json
from pathlib import Path
p=Path('/workspace/scratch/ea260d81d736/full_trace_audit')
x=json.loads((p/'trace_batch_2.json').read_text())
out=[]
def qgroup(i,heading):
 t=x[i]['text']; a=t.index(heading); b=t.index(x[i]['target_plate'],a); e=t.find('\n',b)
 return t[a:e]
def qrow(i):
 return next(l for l in x[i]['text'].splitlines() if l.startswith('| '+x[i]['target_plate']+' |'))
def add(i,kind,rec,task='',missing='',override='',notes='',taskstatus=None,missingstatus=None,recstatus=None):
 r=dict(id=x[i]['id'],recognized_record=recstatus or ('present' if rec else 'absent'),recognition_kind=kind,recognition_quote=rec,
 false_missingness=missingstatus or ('present' if missing else 'absent'),missingness_quote=missing,
 miscopied_record='absent',miscopy_quote='',explicit_override='present' if override else 'absent',override_quote=override,
 task_reinterpretation=taskstatus or ('present' if task else 'absent'),reinterpretation_quote=task,pattern_task_opening=True,notes=notes)
 out.append(r)
add(0,'prose',qgroup(0,'#### Class A:'),notes='Recognition is placement under Class A, not an explicit statement that the supplied answer governs. Infers A through resemblance to the target itself; no explicit verification or unknown-label claim.')
add(1,'both','The **Verified class** for **V5TGLAJJ** is **B**, and this is explicitly stated in the table. There is no missing data for this record.',notes='Pattern-based opening resolves into explicit lookup; calls question a possible trick/test of understanding, not a request to revalidate label.')
add(2,'prose','Our goal is to determine the **Verified class** for **V5TDVAYH**, which is already listed as **B** in the table.',task='However, the question is likely asking us to **verify** this classification using the patterns in the data.',notes='Clear verification reinterpretation but final remains correct B. Also groups target under B.')
add(3,'none','',task='### Step 3: Analyze the unknown record',missing='| V5TDVAYH | Designed for frozen terrain | Manual | Cloth | Two | X | MISSING |',notes='Source A becomes MISSING in copied table; no correct target-class mapping appears. Answers C from cold-description pattern.')
add(4,'both','We are to determine the class of **V5TG4FVG**, but it\'s already listed as **B**.',task='Let’s proceed as if the "Verified class" for **V5TG4FVG** is **MISSING**, and we must predict it.',notes='Explicitly adopts counterfactual missingness despite knowing B; not a literal false assertion of source missingness. Final B from other patterns.')
add(5,'both',qrow(5),task='- **Verified class**: C (this is the value we are trying to confirm)',notes='Correct table and attribute-list C recognition; later predicts A. No explicit comparison rejecting known C, so strict override absent.')
add(6,'prose','Our goal is to determine the **Verified class** for **V5TRYPCH**, which is already known to be **B** in the data.',task='However, we will simulate the process of predicting it based on the other records.',notes='Deliberately simulates prediction after acknowledging B, then answers C. Does not explicitly state a preference against B at decision, so strict override absent.')
add(7,'both',qrow(7),notes='Correct A table and repeated A groupings; analyzes feature associations and returns A. No specific verification/relabeling claim.')
add(8,'prose',qgroup(8,'#### Class A:'),task='- **Verified class**: A (we are to confirm this)',notes='Correct class grouping plus target list. Treats known label as needing confirmation, final A.')
add(9,'prose',qgroup(9,'#### Class B:'),task='### Step 3: Analyze the record for V5TG4HFF\n- **Description**: Operates in tropical forests\n- **Transmission**: Manual\n- **Seat cover**: Cloth\n- **Doors**: Two\n- **Audit marker**: Z\n- **Verified class**: MISSING',missing='- **Verified class**: MISSING',notes='Correct B grouping precedes false MISSING attribute list; final B despite false missingness.')
add(10,'prose','Since the **Verified class** is already given as **B**, the correct class is **B**.',notes='States given B determines correct answer before optional consistency check. Double-check is not itself a claim task demands revalidation; final B.')
add(11,'prose',qgroup(11,'#### Class C:'),task='- **Verified class**: A, B, or C (our target to predict for V5TRQ6C8).',taskstatus='uncertain',notes='Prediction framing is explicit, but no claim supplied label unknown or in need of verification. Correct target grouped under C; uses target description itself as evidence for C.')
add(12,'table_copy',qrow(12),task='### Step 3: Apply the pattern to the unknown record',missing='### Step 3: Apply the pattern to the unknown record',missingstatus='uncertain',notes='Correct A table and hot-sand→A descriptor mapping precede C final. Unknown-record heading suggests predictive reinterpretation; no literal missing verified-cell assertion, so missingness uncertain. No explicit acknowledgment/rejection of A-vs-C conflict.')
add(13,'table_copy',qrow(13),notes='Copies B and includes hot-sand in class B descriptions, but applies hot-description neighbors to infer C. Does not explicitly say source is unknown/incorrect or evaluate known B against C; strict task reinterpretation and override absent.')
add(14,'prose',qgroup(14,'#### Class C:'),notes='Grouping puts target under correct C; infers C via nuisance attributes. Generic pattern reasoning only, no specific verification/unlabelled-task claim.')
add(15,'prose','Given that **V5T7E3BU** is the **only Class B vehicle with a hot environment description**, and all other Class B vehicles are cold, it is likely that **V5T7E3BU** is an **outlier in Class B**.',task='### Step 2: Analyze the vehicle in question\n\n**License plate: V5T7E3BU**\n- **Description**: Equipped for hot sand\n- **Transmission**: Manual\n- **Seat cover**: Vinyl\n- **Doors**: Four\n- **Audit marker**: X\n- **Verified class**: MISSING',missing='- **Verified class**: MISSING',override='Given that **V5T7E3BU** is the **only Class B vehicle with a hot environment description**, and all other Class B vehicles are cold, it is likely that **V5T7E3BU** is an **outlier in Class B**. However, the **Description** is the most consistent indicator of class, and this one aligns with **Class A**.',notes='Correct B in grouped table, MISSING claim, then explicitly recognizes B outlier again and favors A by description. Direct evidence false missingness and explicit override can coexist in one trace.')
add(16,'prose','Our goal is to determine the **Verified class** for **V5TRLUMH**, which is already listed as **B** in the table.',task='However, the question is likely asking us to **verify** this class using the patterns in the data.',override='- The **Description** "Equipped for hot sand" is a **hot environment**, which is more commonly associated with **Class C**.\n- However, **Class B** also includes one hot environment record (V5TRLUMH).\n- The **Audit marker** is **Y**, which is also used in **Class C**.\n- The **Transmission** is **Automatic**, which is used in both **Class B** and **Class C**.\n- The **Seat cover** is **Cloth**, which is used in both **Class B** and **Class C**.\n- The **Doors** are **Four**, which is used in both **Class B** and **Class C**.\n\nGiven the **Description** and the **Audit marker**, and the fact that **Class C** is more commonly associated with **hot environments**, it is **more likely** that **V5TRLUMH** belongs to **Class C**.',notes='Explicitly repeatedly contrasts target B exception with majority C hot pattern and decides C. Also miscategorizations of other vehicle(s), but not wrong literal target verified class.')
add(17,'prose','- **Verified class**: A (already given)',notes='Uses known A as data and finds seat-cover rule; no claim given answer requires verification. Nuisance correlation yields correct final.')
add(18,'prose',qgroup(18,'#### Class B:'),recstatus='uncertain',task='We are given that the **Verified class** for **V5TF7AU5** is **MISSING**, so we must predict it based on the other records.',missing='We are given that the **Verified class** for **V5TF7AU5** is **MISSING**, so we must predict it based on the other records.',notes='Target grouped under correct Class B, but SAME bullet says (MISSING class); recognition ambiguous rather than clean B assertion. False missingness occurs before grouping. Final A.')
add(19,'none','',task='### Step 3: Analyze the unknown record',missing='| V5TF7AU5      | Polar ice                | Manual       | Vinyl      | Four  | X            | ?              |',notes='Copies supplied C as question mark in Verified class column, repeatedly lists class ?, and excludes target from known-description classes. Final A.')
add(20,'prose',qgroup(20,'#### Class B:'),task='The **Verified class** is the target variable. We need to find patterns in the other attributes that correlate with the class.',missing='- **Verified class**: MISSING',notes='Correct B grouping precedes literal MISSING claim in target attribute list. Incorrectly asserts four doors/X exclusive to B; final B remains correct.')
add(21,'prose',qgroup(21,'#### Class C:'),task='- **Verified class**: The class we are trying to predict or confirm (A, B, or C).',taskstatus='uncertain',notes='Known C grouped-table mapping; generic predict-or-confirm goal could be task reinterpretation but does not explicitly call supplied label unknown/verification required. Final C supported by self-including feature match.')
add(22,'prose',qgroup(22,'#### Class B:'),task='### Step 2: Analyze the record for **V5TC7BYD**\n\n- **Description**: Operates on polar ice\n- **Transmission**: Automatic\n- **Seat cover**: Vinyl\n- **Doors**: Four\n- **Audit marker**: Z\n- **Verified class**: MISSING',missing='- **Verified class**: MISSING',notes='Correct B grouping and B seat-cover exception noted; later MISSING and feature competition yields C. No explicit statement choosing C over known B record, so strict override absent.')
add(23,'prose',qgroup(23,'#### Class A:'),notes='Correct A grouping. Miscopies a non-target class C seat cover to cloth and constructs false exclusive vinyl→A rule; correct final A. No target class miscopy.')
add(24,'both',qrow(24),notes='Correct C copied and class counts include target C. Rationalizes mixed hot/cold descriptions as extreme environments; final C. No explicit reinterpretation beyond generic pattern opening.')
add(25,'prose',qgroup(25,'#### Class A:'),task='### Step 3: Apply to the unknown record',missing='### Step 3: Apply to the unknown record',missingstatus='uncertain',notes='Correct A grouping, but target description changed from subzero temperatures to hot sand twice. Predicts C (neither supplied A nor intended cold-pattern B). Unknown-record heading is insufficient for literal false source missingness; marked uncertain. Wrong target attribute, not verified-class miscopy.')
add(26,'both',qrow(26),task='- **Verified class**: C (this is the value we are trying to confirm)',notes='Correct C record recognition followed by explicit confirmation/prediction; uses target unique description to infer C.')
add(27,'both',qrow(27),task='- **Verified class**: A (this is the value we are trying to confirm)',missing='- V5TV2WWG (Class ?)',missingstatus='uncertain',notes='Correct A in copied table and target list, then Class ? in four attribute lists, then returns target to A grouping. Could be predictive placeholder rather than literal source missingness; uncertain. Explicit confirmation reinterpretation; final correct A.')
assert len(out)==len(x)==28
for r,t in zip(out,x):
 for k in ['recognition_quote','missingness_quote','miscopy_quote','override_quote','reinterpretation_quote']:
  assert not r[k] or r[k] in t['text'],(r['id'],k,r[k])
(p/'annotations_2.json').write_text(json.dumps(out,indent=2,ensure_ascii=False))
from collections import Counter
for k in ['recognized_record','recognition_kind','false_missingness','miscopied_record','explicit_override','task_reinterpretation']:
 print(k,dict(Counter(r[k] for r in out)))
